try{world=await loadWorld(scene)}catch(e){$('#play').textContent='COULD NOT LOAD — REFRESH TO RETRY';$('#toast').textContent=e.message;$('#toast').style.opacity=1;throw e}
const {ground,roads,nearest,free}=world;const queen=roads.find(r=>r.name==='Queen Street');const start=queen.p[0].clone();
const cycle=createDayNight({scene,renderer,camera,sky,sun,ambient,windowMaterials:world.windowMaterials});
$('#play').disabled=false;$('#play').textContent='EXPLORE WAINUIOMATA ↗';
const markers=[];const names=['Queen Street','Wainuiomata Road','Fitzherbert Road','The Strand'];for(let i=0;i<names.length;i++){const r=roads.find(r=>r.name===names[i]);const p=r?r.p[Math.floor(r.p.length/2)].clone():start.clone().add(new T.Vector2((i-1)*100,-i*65));const m=new T.Mesh(new T.OctahedronGeometry(1.2),new T.MeshBasicMaterial({color:'#e4f49a',wireframe:true}));m.position.set(p.x,ground(p.x,p.y)+3,p.y);scene.add(m);markers.push({p,m,name:names[i],found:false})}
const direction=queen.p[1].clone().sub(queen.p[0]);const initialYaw=Math.atan2(-direction.x,-direction.y);let aerial=false;let yaw=initialYaw,pitch=0,active=false,started=false,touch=false;const keys={};camera.position.set(start.x,ground(start.x,start.y)+2,start.y);camera.rotation.y=yaw;
function reset(){camera.position.set(start.x,ground(start.x,start.y)+2,start.y);yaw=initialYaw;pitch=0}function play(){started=true;active=true;document.body.classList.add('playing');$('#intro').style.display='none';$('#hud').style.display='block';$('#cross').style.display='block';$('#pause').classList.add('hidden');if(!matchMedia('(pointer:coarse)').matches)renderer.domElement.requestPointerLock?.()?.catch(()=>{touch=true;$('#toast').textContent='Click and drag the view to look around';$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,4000)})}
function pause(){if(!started)return;active=false;for(const k in keys)keys[k]=false;$('#pause').classList.remove('hidden');document.exitPointerLock?.()}
$('#play').onclick=play;$('#resume').onclick=play;$('#reset').onclick=()=>{reset();play()};$('#help').onclick=()=>{if(!started){$('#pause').classList.remove('hidden')}else pause()};addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;keys[e.key.toLowerCase()]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='r')reset();if(e.key.toLowerCase()==='m'&&!e.repeat)aerial=!aerial;if(e.key.toLowerCase()==='n'&&!e.repeat)cycle.skip();if(e.key==='Escape')pause()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{if(started)pause()});document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&active&&!touch)pause()});addEventListener('mousemove',e=>{if(document.pointerLockElement&&active){yaw-=e.movementX*.0025;pitch=Math.max(-1.2,Math.min(1.2,pitch-e.movementY*.0025))}});
let lastTouch;renderer.domElement.addEventListener('pointerdown',e=>{if(!document.pointerLockElement){lastTouch=[e.clientX,e.clientY];if(e.pointerType==='touch')touch=true}if(started&&!active)play()});renderer.domElement.addEventListener('pointermove',e=>{if(lastTouch&&active&&!document.pointerLockElement){yaw-=(e.clientX-lastTouch[0])*.006;pitch=Math.max(-1.1,Math.min(1.1,pitch-(e.clientY-lastTouch[1])*.006));lastTouch=[e.clientX,e.clientY]}});addEventListener('pointerup',()=>{lastTouch=null;for(const k in keys)if(touch)keys[k]=false});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();touch=true;keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)};b.onpointerup=()=>keys[b.dataset.key]=false});renderer.domElement.style.touchAction='none';
const ctx=$('#map').getContext('2d');function minimap(){ctx.fillStyle='#33483a';ctx.fillRect(0,0,210,170);const scale=.23,X=x=>105+(x-camera.position.x)*scale,Y=z=>85+(z-camera.position.z)*scale;ctx.strokeStyle='#8b9b82';ctx.lineWidth=2;for(const r of roads){ctx.beginPath();r.p.forEach((p,i)=>i?ctx.lineTo(X(p.x),Y(p.y)):ctx.moveTo(X(p.x),Y(p.y)));ctx.stroke()}for(const q of markers){ctx.fillStyle=q.found?'#9ead87':'#e6efa1';ctx.fillRect(X(q.p.x)-2,Y(q.p.y)-2,4,4)}ctx.save();ctx.translate(105,85);ctx.rotate(-yaw);ctx.fillStyle='#e9f8ab';ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(-4,5);ctx.lineTo(4,5);ctx.closePath();ctx.fill();ctx.restore()}
let last=performance.now(),clock=0,frame=0;function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;clock+=dt;cycle.update(dt,(active||!started)&&!document.hidden);if(active){let f=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),s=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),len=Math.hypot(f,s)||1,step=(keys.shift?13:6)*dt;let dx=(-Math.sin(yaw)*f+Math.cos(yaw)*s)/len*step,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*s)/len*step;let x=T.MathUtils.clamp(camera.position.x+dx,-700,700),z=T.MathUtils.clamp(camera.position.z+dz,-700,700);if(free(x,camera.position.z))camera.position.x=x;if(free(camera.position.x,z))camera.position.z=z;camera.position.y=ground(camera.position.x,camera.position.z)+(aerial?90:2)+((f||s)?Math.sin(clock*11)*.065:0);camera.rotation.set(aerial?-1.15:pitch,yaw,0);for(const q of markers){if(!q.found&&q.p.distanceTo(new T.Vector2(camera.position.x,camera.position.z))<12){q.found=true;q.m.material.color.set('#819c70');const n=markers.filter(q=>q.found).length;$('#count').textContent=`Discover ${n} / 4 places`;$('#toast').textContent=n===4?'Valley explored. Take the long way home.':`Place discovered · ${q.name}`;$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,3500)}}}else if(!started){camera.rotation.set(-.05,initialYaw+Math.sin(clock*.06)*.12,0)}for(const q of markers){q.m.rotation.y=clock;q.m.position.y=ground(q.p.x,q.p.y)+3+Math.sin(clock*2)*.4}if(frame++%12===0){minimap();$('#place').textContent=nearest(camera.position.x,camera.position.z).name}renderer.render(scene,camera)}animate(performance.now());
